    private static readonly IReadOnlyDictionary<Spell, TalentAbility> BySpell =
        Definitions.ToDictionary(ability => ability.Spell.Spell);

    public static IReadOnlyList<TalentAbility> All { get; } = Array.AsReadOnly(Definitions);

    public static bool TryGet(Spell spell, out TalentAbility ability) => BySpell.TryGetValue(spell, out ability);

    private static TalentAbility Add(Spell spell, MirClass @class, CombatSpecialisation spec, string name,
        AbilityTarget target, AbilityTheme theme, byte range, byte mana, ushort cooldown, ushort windup,
        float scale, byte icon, byte level, TalentAbilityKind kind, string description,
        TalentControl control = TalentControl.None) =>
        new(new(spell, @class, spec, name, target, theme, range, mana, cooldown, windup,
            scale > 0 ? (ushort)6 : (ushort)0, scale, icon, description, level), kind, control);
}
